cases.script:
if ! builtin type finfo >/dev/null 2>&1; then
  finfo() {
    local option=$1 mask mode path
    shift
    case $option in
      -o) stat -c '%a' -- "$@" ;;
      -p)
        for path in "$@"; do
          mode=$(stat -c '%A' -- "$path")
          mode=${mode:1}
          user=${mode:0:3}; user=${user//-/}
          group=${mode:3:3}; group=${group//-/}
          other=${mode:6:3}; other=${other//-/}
          printf 'u=%s,g=%s,o=%s\n' "$user" "$group" "$other"
        done ;;
      -P)
        mask=$1; shift
        for path in "$@"; do
          mode=$(stat -c '%a' -- "$path")
          printf '%o\n' "$((8#$mode & 8#$mask))"
        done ;;
    esac
  }
fi
: > sticky
chmod 1777 sticky
finfo -o sticky
finfo -p sticky
finfo -P 7777 sticky

if ! builtin type finfo >/dev/null 2>&1; then
  finfo() {
    local option=$1 format
    shift
    case $option in
      -u) format='%u' ;;
      -U) format='%U' ;;
      -g) format='%g' ;;
      -G) format='%G' ;;
    esac
    stat -c "$format" -- "$@"
  }
fi
: > owner
finfo -u owner
finfo -U owner
finfo -g owner
finfo -G owner
